assert (P/'captures/current-build.png').exists(), 'Restore the baseline capture from git.'
directions=[dict(id='dusk',name='After-hours dusk',tag='Clock out. Cause chaos.',desc='Warm work lights. Cool windows. One very overdue escape.',bg='#101d24',surface='#21343b',accent='#ff9a1a',ink='#fff2dc',muted='#bdcbd0',secondary='#679e9c',material='Walnut · quiet carpet · eggshell walls',recipe='Warm existing desk-area lights; cool ambient fill. Lower wall normal strength, remove oversized black floor seams, preserve muted dusk windows. Shared rough materials; emissive signage, not extra shadow lights.',sign='CLOCK OUT →',font='Georgia,serif'),dict(id='toybox',name='Toybox office',tag='Serious work. Silly wheels.',desc='Chunky furniture, sticker-like signs, and coffee-sized ambition.',bg='#e8efe0',surface='#f8f5e8',accent='#b73c30',ink='#20362d',muted='#496354',secondary='#639c87',material='Molded mint plastic · butter fabric · coral enamel',recipe='Broad soft color masses and matte surfaces. Rounded, chunky furniture silhouettes using low-poly meshes. Warm cream walls, subdued mint floor. Springy UI response respects reduced motion; avoid rainbow clutter.',sign='THIS WAY, SLACKER →',font='Trebuchet MS,sans-serif'),dict(id='emergency',name='Corporate emergency',tag='Evacuate the ordinary.',desc='An absurdly official safety system for an unofficial chair race.',bg='#171918',surface='#272b27',accent='#ff8b38',ink='#f3f0df',muted='#bdc3b7',secondary='#b6dd67',material='Powder-coated metal · bone paper · charcoal rubber',recipe='Industrial signage and bold silhouettes. Large floor numbers, bone-white walls with limited orange accents. Use broad route markers, never repeating high-frequency hazard stripes across the floor. No neon wash.',sign='AUTHORIZED ESCAPE →',font='Impact,Arial Narrow,sans-serif')]
css='''*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.55 -apple-system,BlinkMacSystemFont,sans-serif}a{color:inherit}button,a{touch-action:manipulation}button:focus-visible,a:focus-visible{outline:3px solid var(--secondary);outline-offset:5px}header,main,footer{max-width:1440px;margin:auto;padding:28px 48px}header{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid var(--secondary);gap:20px}.brand{font-weight:900;letter-spacing:-.04em;font-size:24px}.brand small{display:block;font:12px/1.6 monospace;letter-spacing:.15em;color:var(--muted)}nav{display:flex;flex-wrap:wrap;gap:8px}nav a,button{border:1px solid var(--muted);background:transparent;color:var(--ink);padding:10px 16px;text-decoration:none;border-radius:4px;font:700 14px/1.3 inherit;cursor:pointer}nav a[aria-current=page],button.primary{background:var(--accent);color:var(--bg);border-color:var(--accent)}.eyebrow{font:700 12px/1.5 monospace;letter-spacing:.15em;text-transform:uppercase;color:var(--muted)}h1{font-family:var(--display);font-size:clamp(44px,6.3vw,92px);line-height:.99;font-weight:900;letter-spacing:-.055em;max-width:850px;margin:20px 0}h2{font-size:26px;letter-spacing:-.035em;margin:8px 0 18px}h3{margin:8px 0;font-size:18px}p{max-width:720px;color:var(--muted)}.intro{display:grid;grid-template-columns:1fr 270px;gap:36px;padding:36px 0}.stamp{border:1px solid var(--secondary);padding:22px;align-self:center;transform:rotate(3deg);font:16px monospace}.stamp strong{display:block;font-size:52px;color:var(--accent);line-height:1.2}.stage{position:relative;background:var(--surface);padding:24px;border:1px solid var(--secondary);min-height:330px;overflow:hidden}.stage-grid{display:grid;grid-template-columns:1fr 1fr;gap:36px;align-items:center;padding:45px 0}.clock{font:800 46px/1 monospace;color:var(--ink)}.hudtop{display:flex;justify-content:space-between;align-items:start;gap:16px}.floor{font:700 14px monospace;border-left:5px solid var(--accent);padding-left:16px}.floor strong{font-size:26px;display:block}.sign{background:var(--secondary);color:var(--bg);font:900 clamp(18px,2.5vw,34px)/1.2 var(--display);padding:22px;text-align:center;box-shadow:0 9px 0 var(--bg)}.mocknote{font:12px monospace;color:var(--muted)}.hudbottom{display:flex;justify-content:space-between;gap:20px;align-items:end}.speed strong{font:800 36px monospace}.meter{height:8px;width:160px;background:var(--bg);margin-top:8px}.meter i{display:block;height:100%;width:35%;background:var(--accent);transition:width .25s}.boosting .meter i{width:100%}.boosting .status{color:var(--accent)}.columns{display:grid;grid-template-columns:1fr 1fr;gap:40px;margin:40px 0}.swatches{display:flex;gap:10px;flex-wrap:wrap}.swatch{flex:1;min-width:80px}.chip{height:76px;border:1px solid var(--muted);border-radius:4px}.swatch code{font-size:12px}.specimen{padding:24px;background:var(--surface);margin:20px 0;border-bottom:3px solid var(--accent)}.surfaces{display:flex;gap:12px;height:84px}.surfaces i{display:block;flex:1;background:var(--secondary);border-radius:14px;box-shadow:inset 0 -12px 0 #0002}.surfaces i:nth-child(2){background:var(--accent);border-radius:28px}.surfaces i:nth-child(3){background:var(--ink);border-radius:3px}.baseline{display:grid;grid-template-columns:1.2fr 1fr;gap:28px;padding:28px 0;border-top:1px solid var(--secondary)}.baseline img{width:100%;height:auto;display:block;border-radius:3px}.actions{display:flex;flex-wrap:wrap;gap:10px;margin:18px 0}.output{white-space:pre-wrap;overflow-wrap:anywhere;font:13px/1.5 monospace;background:var(--surface);padding:18px;border:1px solid var(--secondary)}footer{font-size:13px;color:var(--muted);border-top:1px solid var(--secondary)}.toybox .stage{border:3px solid var(--ink);border-radius:28px;box-shadow:8px 8px 0 var(--secondary)}.toybox .intro{grid-template-columns:270px 1fr}.toybox .stamp{grid-column:1;grid-row:1;transform:rotate(-5deg);background:var(--accent);color:var(--surface);border-radius:24px}.toybox .stamp strong{color:var(--surface)}.toybox .heading{grid-column:2}.toybox .columns{grid-template-columns:1.2fr 1fr}.toybox .sign{transform:rotate(-4deg);border:3px solid var(--ink);border-radius:40px;color:var(--ink);box-shadow:4px 5px 0 var(--ink)}.toybox button.primary{color:var(--surface)}.toybox nav a[aria-current=page]{color:var(--surface)}.emergency h1{text-transform:uppercase;letter-spacing:-.025em;max-width:680px}.emergency .intro{border-bottom:10px solid var(--accent)}.emergency .stamp{transform:none;border:0;border-left:8px solid var(--accent)}.emergency .stage{border:0;border-left:12px solid var(--accent);margin-top:28px}.emergency .columns{grid-template-columns: .8fr 1.2fr}.emergency .sign{background:var(--accent)}@media(max-width:760px){header,main,footer{padding:22px}header{align-items:start;flex-direction:column}.intro,.toybox .intro,.columns,.toybox .columns,.emergency .columns,.baseline{grid-template-columns:1fr}.toybox .heading{grid-column:1;grid-row:1}.toybox .stamp{grid-column:1;grid-row:2}.stamp{max-width:270px}.stage-grid{grid-template-columns:1fr;gap:25px;padding:28px 0}.clock{font-size:34px}.stage{padding:18px}.floor strong{font-size:20px}.hudbottom{align-items:start;flex-direction:column}.sign{font-size:23px}.intro{gap:20px}.columns{gap:20px}.toybox .stage{box-shadow:4px 4px 0 var(--secondary)}h1{font-size:52px}}@media(prefers-reduced-motion:reduce){*{transition:none!important}}'''
(P/'panel.css').write_text(css)
for d in directions:
    links=''.join(f'<a href="{x["id"]}.html"'+(' aria-current="page"' if x==d else '')+f'>{i+1:02} {x["name"]}</a>' for i,x in enumerate(directions))
    colors=''.join(f'<div class="swatch"><div class="chip" style="background:{d[k]}"></div><h3>{k.title()}</h3><code>{d[k]}</code></div>' for k in ['bg','surface','ink','accent','secondary'])
    html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{d['name']} — Friday design panel</title><link rel="stylesheet" href="panel.css"></head><body class="{d['id']}" style="--bg:{d['bg']};--surface:{d['surface']};--ink:{d['ink']};--muted:{d['muted']};--accent:{d['accent']};--secondary:{d['secondary']};--display:{d['font']}"><header><div class="brand">FRIDAY / 5PM<small>EVACUATION · ART DIRECTION LAB</small></div><nav aria-label="Design direction">{links}</nav></header><main><section class="intro"><div class="heading"><div class="eyebrow">{'Recommended direction / ' if d['id']=='dusk' else 'Alternative direction / '}{d['name']}</div><h1>{d['tag']}</h1><p>{d['desc']}</p></div><aside class="stamp">EMPLOYEE EXIT PASS<strong>17:00</strong>Work ends. Race begins.</aside></section><div class="eyebrow">01 / Playable interface specimen · illustrative values</div><section class="stage" aria-label="HUD design sample"><div class="hudtop"><div class="floor">EVACUATION<strong>01 / OPEN PLAN</strong></div><div class="clock">02:00</div></div><div class="stage-grid"><div><div class="eyebrow">Wayfinding system</div><div class="sign">{d['sign']}</div></div><div><h2>Keep the escape route clear.</h2><p>This is a UI and signage composition—not a new gameplay render. The center of the actual screen stays open for the chair, hazards, and route ahead.</p></div></div><div class="hudbottom"><div class="speed"><strong id="speed">00</strong> km/h<div class="meter"><i></i></div></div><div><strong class="status" id="status">COFFEE BOOST / READY</strong><div class="actions"><button id="boost" class="primary" aria-pressed="false">Preview boost</button></div></div></div></section><section class="columns"><div><div class="eyebrow">02 / Shared visual tokens</div><h2>One palette. Every surface.</h2><div class="swatches">{colors}</div><div class="specimen"><div class="surfaces" aria-label="Abstract material and shape samples"><i></i><i></i><i></i></div><h3>{d['material']}</h3><p>Abstract shape/material specimens. Broad surfaces, readable edges, no noisy micro-patterns.</p></div></div><div><div class="eyebrow">03 / Godot translation</div><h2>Art direction, not expensive effects.</h2><p>{d['recipe']}</p><ul><li>Retain GL Compatibility and the existing quality presets.</li><li>Use shared material resources; duplicate before instance animation.</li><li>Keep decorative props out of collision and checkpoint paths.</li><li>No additional real-time shadow lights, SSAO, or bloom dependency.</li><li>Ceiling decorations cast no shadows. Keep ground detail above the slab.</li></ul><div class="actions"><button id="export">Export Godot palette</button><button id="copy">Copy recipe</button></div><div role="status" id="feedback" class="mocknote">Preview only. Game-wide implementation awaits your direction choice.</div><pre class="output" id="recipe">{d['name']}\nBackground: {d['bg']}\nSurface: {d['surface']}\nText: {d['ink']}\nAccent: {d['accent']}\nSecondary: {d['secondary']}\n\n{d['recipe']}</pre></div></section><section class="baseline"><figure style="margin:0"><img src="captures/current-build.png" alt="Real Godot baseline: chair in an office, with opening controls overlay"><figcaption class="mocknote">CURRENT GODOT BUILD · unmodified engine capture</figcaption></figure><div><div class="eyebrow">04 / Before we restyle</div><h2>The game works. The surfaces compete.</h2><p>The baseline has coarse wall texture, heavy floor seams, flat lighting, and scattered HUD elements. Simplifying these comes before adding more tiny props.</p><p>First implementation slice: calmer walls and carpet, deliberate warm/cool light separation, unified signage, and a compact HUD. Gameplay, controls, elevator positions, and LAN behavior stay intact.</p><p class="mocknote">Assumptions: stylized office comedy, laptop/mobile performance, existing orange identity. HTML specimens are concepts; the image at left is the real game. No Blender or engine migration required.</p></div></section></main><footer>FRIDAY 5PM: EVACUATION / Design template exploration. Choose a direction in conversation before applying it to the game. Offline panel · no external dependencies.</footer><script>
const feedback=document.getElementById('feedback');let active=false;document.getElementById('boost').onclick=()=>{{active=!active;document.querySelector('.stage').classList.toggle('boosting',active);document.getElementById('speed').textContent=active?'48':'00';document.getElementById('status').textContent=active?'COFFEE BOOST / ACTIVE':'COFFEE BOOST / READY';document.getElementById('boost').setAttribute('aria-pressed',String(active));document.getElementById('boost').textContent=active?'Reset preview':'Preview boost';}};
const recipe=document.getElementById('recipe').textContent;document.getElementById('copy').onclick=async()=>{{try{{await navigator.clipboard.writeText(recipe);feedback.textContent='Recipe copied.';}}catch(e){{const r=document.createRange();r.selectNodeContents(document.getElementById('recipe'));const s=window.getSelection();s.removeAllRanges();s.addRange(r);feedback.textContent='Recipe selected. Press Cmd+C or Ctrl+C to copy.';}}}};
document.getElementById('export').onclick=()=>{{const text='extends RefCounted\\n# Concept palette: {d['name']} — not yet applied\\n'+{repr([[k.upper(),d[k]] for k in ['bg','surface','ink','accent','secondary']])}.map(([k,v])=>'const '+k+' = Color("'+v+'")').join('\\n')+'\\n';const a=document.createElement('a');const url=URL.createObjectURL(new Blob([text],{{type:'text/plain'}}));a.href=url;a.download='{d['id']}_palette.gd';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);feedback.textContent='Godot palette exported. This does not modify the game.';}};try{{localStorage.setItem('friday-design-preview','{d['id']}')}}catch(e){{}}
</script></body></html>'''
    (P/f'{d["id"]}.html').write_text(html)
(P/'index.html').write_text((P/'dusk.html').read_text())
print('Generated index and 3 direction pages.')
